import { readFileSync, writeFileSync } from 'fs'

const SEED_PATH = 'src/lib/seed-data.ts'
const cb = (d) => `https://logo.clearbit.com/${d}`

let toolNum = 300
function add(cat, slug, name, descEs, descEn, pm, ps, rating, os, tags, domain, website) {
  toolNum++
  const w = website || `https://${domain}`
  return {
    id: `tool-${toolNum}`, slug, name,
    logo_url: cb(domain),
    description_es: descEs.replace(/'/g, "\\'"),
    description_en: descEn.replace(/'/g, "\\'"),
    category_id: cat, price_model: pm, price_starting: ps,
    website_url: w, affiliate_url: null,
    rating_g2: rating, rating_capterra: null,
    is_open_source: os || false, is_verified: false, listing_tier: 'free',
    tags: tags || [], alternatives: []
  }
}

