const all = [...newTools, ...more, ...more2, ...more3, ...more4]

const seed = readFileSync(SEED_PATH, 'utf-8')

const toolRegex = /\n  \{\s*\n    id: 'tool-[\s\S]*?\n  \},?/g
const matches = seed.match(toolRegex) || []
const seen = new Set()
const existing = []
for (const t of matches) {
  const m = t.match(/id: '(tool-\d+)'/)
  if (m && !seen.has(m[1])) { seen.add(m[1]); existing.push(t.trim()) }
}

const genIdx = seed.indexOf('export const generatedContent:')
const header = seed.slice(0, genIdx > 0 ? genIdx : seed.length - 1)
const footer = seed.slice(genIdx > 0 ? genIdx : seed.length)

const ts = all.map(t => `  {
    id: '${t.id}', slug: '${t.slug}', name: '${t.name}',
    logo_url: '${t.logo_url}',
    description_es: '${t.description_es}',
    description_en: '${t.description_en}',
    category_id: '${t.category_id}', price_model: '${t.price_model}', price_starting: ${t.price_starting},
    website_url: '${t.website_url}', affiliate_url: null,
    rating_g2: ${t.rating_g2}, rating_capterra: null, is_open_source: ${t.is_open_source}, is_verified: false, listing_tier: 'free',
    tags: [${t.tags.map(x => `'${x}'`).join(', ')}],
  }`)

const toolsDecl = `export const tools: (Tool & { alternatives?: { alternative_slug: string; rank: number }[] })[] = [`
const newContent = seed.slice(0, seed.indexOf('export const categories:')) +
  seed.slice(seed.indexOf('export const categories:'), seed.indexOf('export const tools:')).trim() + '\n\n' +
  toolsDecl + '\n' +
  existing.join(',\n') + ',\n' +
  ts.join(',\n') + '\n]\n\n' +
  footer

writeFileSync(SEED_PATH, newContent)
console.log(`✅ Added ${all.length} tools (existing: ${existing.length}, total: ${existing.length + all.length})`)
